from bst import BinarySearchTree


def test_constructs_without_args():
    tree = BinarySearchTree()
    assert tree is not None


def test_insert_returns_none():
    tree = BinarySearchTree()
    assert tree.insert(5) is None


def test_search_finds_inserted_values():
    tree = BinarySearchTree()
    values = [50, 30, 70, 20, 40, 60, 80]
    for v in values:
        tree.insert(v)
    for v in values:
        assert tree.search(v) is True


def test_search_empty_tree_returns_false():
    tree = BinarySearchTree()
    assert tree.search(1) is False


def test_search_absent_values_smaller_larger_between():
    tree = BinarySearchTree()
    for v in [50, 30, 70]:
        tree.insert(v)
    assert tree.search(10) is False  # smaller than all
    assert tree.search(100) is False  # larger than all
    assert tree.search(40) is False  # between 30 and 50


def test_duplicate_insert_does_not_raise_and_is_found():
    tree = BinarySearchTree()
    tree.insert(7)
    assert tree.insert(7) is None
    assert tree.search(7) is True
    tree.insert(3)
    tree.insert(3)
    assert tree.search(3) is True
    assert tree.search(7) is True


def test_deep_tree_no_recursion_error():
    tree = BinarySearchTree()
    n = 5000  # degenerate chain deeper than default recursion limit
    for i in range(n):
        tree.insert(i)
    assert tree.search(0) is True
    assert tree.search(n - 1) is True
    assert tree.search(n) is False


def test_string_values():
    tree = BinarySearchTree()
    for s in ["m", "c", "x"]:
        tree.insert(s)
    assert tree.search("c") is True
    assert tree.search("d") is False

